INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will no Fed rate cuts happen in 2026?', 'This market will resolve according to the exact amount of cuts of 25 basis points in 2026 by the Fed (including any cuts made during the December meeting). Emergency rate cuts outside of scheduled FOMC meetings will also count toward the total number of cuts in 2026. This market will remain open until December 31, 2026, 11:59 PM ET, to account for any such emergency actions. For example, if the Fed cuts rates by 50 bps after a meeting, it would be considered 2 cuts (of 25 bps each). This market ', 'world', 'active', 3088574.35, 504880.39, 3089074.35, 505380.39);
